<script setup lang="ts">
import { ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useAuth } from '../stores/auth'; import AuthForm from '../components/AuthForm.vue'; import AuthShell from '../components/AuthShell.vue'
const router = useRouter(); const route = useRoute(); const { authenticate, state } = useAuth(); const error = ref(route.query.message?.toString() || '')
async function login(payload: { email: string; password: string }) { error.value = ''; try { await authenticate('login', payload); router.push('/dashboard') } catch (e: any) { const status = e.response?.status; error.value = status === 401 ? 'Correo o contraseña incorrectos.' : status ? 'No fue posible iniciar sesión. Inténtalo nuevamente.' : 'No fue posible conectar con el servidor. Inténtalo nuevamente.' } }
</script>
<template><AuthShell eyebrow="TU ESPACIO DE TRABAJO" title="Iniciar sesión" subtitle="Ingresa tus credenciales para acceder al panel de administración."><v-alert v-if="error" icon="mdi-alert-circle-outline" variant="tonal" density="comfortable" class="auth-error-alert mb-5" closable @click:close="error = ''">{{ error }}</v-alert><AuthForm mode="login" :loading="state.loading" @submit="login"><template #options><div class="login-options"><v-checkbox density="compact" hide-details label="Recordarme en este dispositivo" color="primary" /><router-link class="small-link" to="/recuperar-contrasena">¿Olvidaste tu contraseña?</router-link></div></template></AuthForm><v-divider class="my-5" /><p class="text-center text-caption text-medium-emphasis">¿Aún no tienes una cuenta? <router-link class="small-link" to="/registro">Crear cuenta</router-link></p></AuthShell></template>
<style scoped>.small-link { color:#3364a2;font-weight:700;text-decoration:none }.small-link:hover { color:#3867de;text-decoration:underline }.login-options{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}.login-options :deep(.v-label),.login-options .small-link{font-size:12px;line-height:1.25}.login-options :deep(.v-selection-control){min-height:30px}.login-options :deep(.v-selection-control__wrapper){transform:scale(.84);margin-inline:-3px}.login-options .small-link{white-space:nowrap}@media(max-width:390px){.login-options{align-items:flex-start;flex-wrap:wrap}.login-options .small-link{padding-top:7px}}</style>
